class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        import sys
        sys.setrecursionlimit(400000)
        n = len(nums)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        total = sum(nums)
        def feasible(v):
            cuts = 0
            def dfs(u, p):
                nonlocal cuts
                s = nums[u]
                for w in g[u]:
                    if w != p:
                        s += dfs(w, u)
                if s == v:
                    cuts += 1
                    return 0
                return s
            dfs(0, -1)
            return cuts == total // v
        ans = 0
        v = 1
        while v * v <= total:
            if total % v == 0:
                for cand in {v, total // v}:
                    if feasible(cand):
                        ans = max(ans, total // cand - 1)
            v += 1
        return ans

