class Solution {
public:
    int total_, cuts_;
    vector<vector<int>> g_;
    vector<int>* nums_;
    int dfs(int u, int p, int v) {
        int s = (*nums_)[u];
        for (int w : g_[u]) if (w != p) s += dfs(w, u, v);
        if (s == v) { cuts_++; return 0; }
        return s;
    }
    bool feasible(int v, vector<int>& nums) {
        cuts_ = 0;
        dfs(0, -1, v);
        return cuts_ == total_ / v;
    }
    int componentValue(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        g_.assign(n, {}); nums_ = &nums;
        for (auto& e : edges) { g_[e[0]].push_back(e[1]); g_[e[1]].push_back(e[0]); }
        total_ = accumulate(nums.begin(), nums.end(), 0);
        int ans = 0;
        for (int v = 1; (long long)v * v <= total_; v++) {
            if (total_ % v) continue;
            for (int cand : {v, total_ / v}) {
                if (feasible(cand, nums)) ans = max(ans, total_ / cand - 1);
            }
        }
        return ans;
    }
};

