class Solution {
    private List<List<Integer>> g;
    private int[] nums;
    private int cuts, total;
    private int dfs(int u, int p, int v) {
        int s = nums[u];
        for (int w : g.get(u)) if (w != p) s += dfs(w, u, v);
        if (s == v) { cuts++; return 0; }
        return s;
    }
    private boolean feasible(int v) {
        cuts = 0;
        dfs(0, -1, v);
        return cuts == total / v;
    }
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        total = Arrays.stream(nums).sum();
        int ans = 0;
        for (int v = 1; (long)v * v <= total; v++) {
            if (total % v != 0) continue;
            for (int cand : new int[]{v, total / v})
                if (feasible(cand)) ans = Math.max(ans, total / cand - 1);
        }
        return ans;
    }
}

