var componentValue = function(nums, edges) {
    const n = nums.length, g = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { g[a].push(b); g[b].push(a); }
    const total = nums.reduce((x, y) => x + y, 0);
    function feasible(v) {
        let cuts = 0;
        function dfs(u, p) {
            let s = nums[u];
            for (const w of g[u]) if (w !== p) s += dfs(w, u);
            if (s === v) { cuts++; return 0; }
            return s;
        }
        dfs(0, -1);
        return cuts === Math.floor(total / v);
    }
    let ans = 0;
    for (let v = 1; v * v <= total; v++) {
        if (total % v) continue;
        for (const cand of new Set([v, total / v]))
            if (feasible(cand)) ans = Math.max(ans, total / cand - 1);
    }
    return ans;
};
